import{_ as o}from"./chunks/02.DG6QN1-y.js";import{_ as e}from"./chunks/multiselect.Gtk6Hii5.js";import{_ as a,o as r,c as n,aa as s}from"./chunks/framework.BAs_AphD.js";const l="/buildary-help-preview/media/cs/tickets/ukoly_ikony.png",i="/buildary-help-preview/media/cs/tickets/filtr_parametru.png",k="/buildary-help-preview/media/cs/tickets/filtr_mrizky.png",d="/buildary-help-preview/academy/img/seznam-ukolu/05.webp",p="/buildary-help-preview/media/cs/tickets/kanban2_prace_s_ukoly.png",j=JSON.parse('{"title":"Seznam úkolů a filtry","description":"","frontmatter":{"title":"Seznam úkolů a filtry","wiki":"cs:tickets:task_grid"},"headers":[],"relativePath":"tickets/task_grid.md","filePath":"tickets/task_grid.md","lastUpdated":1794209661000}'),u={name:"tickets/task_grid.md"};function g(v,t,m,h,y,c){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="seznam-ukolu-a-filtry" tabindex="-1">Seznam úkolů a filtry <a class="header-anchor" href="#seznam-ukolu-a-filtry" aria-label="Permalink to &quot;Seznam úkolů a filtry&quot;">​</a></h1><p><strong>Seznam úkolů</strong> je hlavní přehled úkolů stavby. Úkoly v něm vyhledáte a vyfiltrujete, otevřete, hromadně vyexportujete nebo smažete. Stejné úkoly můžete zobrazit také jako kartičky v <strong>Kanbanu</strong> a stav měnit přetažením.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/seznam-ukolu">Najít úkoly, filtrovat a exportovat je</a> v Akademii.</p><figure class="shot" style="--w:760px;"><img src="'+o+'" alt="Seznam úkolů s filtry v horním řádku, tlačítky Nový úkol a Export, výběrem pohledu a mřížkou úkolů" loading="lazy"></figure><p>Seznam otevřete v levém panelu volbou <strong>Seznam úkolů</strong>. Stránka má tři části:</p><ul><li><strong>horní řádek filtrů</strong> – určuje, které úkoly se načtou,</li><li><strong>lišta nad mřížkou</strong> – <strong>Nový úkol</strong>, <strong>Export</strong>, výběr a správa pohledů a přepínač <strong>Tabulka</strong> / <strong>Kanban</strong>,</li><li><strong>mřížka</strong> (tabulka) úkolů – s řazením, filtry ve sloupcích a stránkováním dole.</li></ul><h2 id="filtry-v-hornim-radku" tabindex="-1">Filtry v horním řádku <a class="header-anchor" href="#filtry-v-hornim-radku" aria-label="Permalink to &quot;Filtry v horním řádku&quot;">​</a></h2><p>Filtry v horním řádku omezují, které úkoly se načtou ze serveru. Na stavbě se stovkami úkolů tak seznam načtete rychleji.</p><table tabindex="0"><thead><tr><th>Filtr</th><th>Možnosti</th></tr></thead><tbody><tr><td><strong>Hledané slovo nebo výraz</strong></td><td>Prohledá předmět, popis, vyjádření, kategorie a štítky. Najde i skloňované tvary, slovo tedy stačí zadat v základním tvaru.</td></tr><tr><td><strong>Vztah k úkolu</strong></td><td><strong>Všechny úkoly</strong>, <strong>Všechny mé úkoly</strong>, <strong>Mnou vytvořené úkoly</strong>, <strong>Mnou řešené úkoly</strong>, <strong>Mnou schvalované</strong>, <strong>Ostatní úkoly</strong></td></tr><tr><td><strong>Aktuálnost úkolu</strong></td><td><strong>Všechny úkoly</strong>, <strong>Aktuální</strong>, <strong>Zpožděné</strong>, <strong>Výhledové</strong>, <strong>Bez termínu</strong>, <strong>Neukončené</strong>, <strong>Ukončené</strong></td></tr><tr><td><strong>Část stavby</strong></td><td>Jen úkoly vybrané části stavby. Části nastavuje administrátor – viz <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>.</td></tr><tr><td><strong>Zobrazení</strong></td><td><strong>Stavba</strong> – úkoly otevřené stavby. <strong>Přehled</strong> – úkoly ze všech vašich staveb se zapnutým Managementem úkolů.</td></tr></tbody></table><p>Filtry se zachovají i po přepnutí do Kanbanu.</p><h2 id="mrizka-ukolu" tabindex="-1">Mřížka úkolů <a class="header-anchor" href="#mrizka-ukolu" aria-label="Permalink to &quot;Mřížka úkolů&quot;">​</a></h2><p>V řádku každého úkolu najdete:</p><table tabindex="0"><thead><tr><th>Prvek</th><th>Co udělá</th></tr></thead><tbody><tr><td>zaškrtávací pole</td><td>vybere úkol pro <a href="#hromadne-operace">hromadné operace</a></td></tr><tr><td>ikona tužky nebo <strong>předmět</strong> úkolu</td><td>otevře detail úkolu – viz <a href="/buildary-help-preview/tickets/task_edit">Řešit a schválit úkol</a></td></tr><tr><td>ikona koše</td><td>smaže úkol</td></tr><tr><td>šipka u předmětu</td><td>rozbalí pod řádkem popis úkolu a poslední vyjádření</td></tr><tr><td>oranžová ikona bubliny</td><td>je jen u úkolů s vyjádřením, otevře celé vlákno vyjádření</td></tr></tbody></table><p>Popis a vyjádření se v seznamu jen zobrazují, upravit je můžete v detailu úkolu.</p><figure class="shot" style="--w:600px;"><img src="'+l+'" alt="Řádky seznamu úkolů s ikonou tužky a koše, ikonou vyjádření a rozbaleným popisem a vyjádřením" loading="lazy"></figure><p>Mřížka zobrazuje sloupce podle zvoleného pohledu, například <strong>Kód</strong>, <strong>Předmět</strong>, <strong>Stav</strong>, <strong>Priorita</strong>, <strong>Plánovaný konec</strong>, <strong>Kategorie</strong>, <strong>Řešitelé</strong>, <strong>Štítky</strong> nebo <strong>Související úkoly</strong>. Které sloupce se zobrazí, v jakém pořadí a jak budou seřazené nebo seskupené, nastavíte podle stránky <a href="/buildary-help-preview/tickets/taskviews">Přizpůsobit pohledy</a>.</p><p>Dole pod mřížkou přecházíte mezi stránkami a v poli <strong>Počet záznamů na stránku</strong> nastavíte, kolik úkolů se na stránce zobrazí.</p><h2 id="filtry-ve-sloupcich" tabindex="-1">Filtry ve sloupcích <a class="header-anchor" href="#filtry-ve-sloupcich" aria-label="Permalink to &quot;Filtry ve sloupcích&quot;">​</a></h2><p>Filtry ve sloupcích už pracují jen s úkoly načtenými podle horního řádku.</p><ul><li><strong>Filtrační řádek</strong> pod záhlavím mřížky – podle sloupce do něj zadáte text, vyberete hodnotu ze seznamu nebo datum v kalendáři. Filtrační řádek zapnete a vypnete v menu <strong>⋮</strong> nad mřížkou volbou <strong>Zapnout filtrační řádek</strong>.</li><li><strong>Ikona trychtýře</strong> v záhlaví některých sloupců (například <strong>Stav</strong>, <strong>Priorita</strong>, <strong>Kategorie</strong>) – vyberete v ní více hodnot najednou. Počet vybraných hodnot se ukáže u ikony. Tlačítkem <strong>Vymazat filtry</strong> výběr zrušíte.</li></ul><figure class="shot" style="--w:560px;"><img src="'+i+'" alt="Otevřený filtr Filtrace ve sloupci Priorita s výběrem více hodnot a zvýrazněnou ikonou filtru u sloupce Stav" loading="lazy"></figure><p>Dokud je ve sloupcích nastavený nějaký filtr, svítí nad mřížkou oranžové upozornění s vykřičníkem. Křížkem v něm vypnete všechny filtry ve sloupcích najednou.</p><figure class="shot" style="--w:600px;"><img src="'+k+'" alt="Oranžové upozornění na zapnuté filtry nad mřížkou a filtr Vysoká ve sloupci Priorita" loading="lazy"></figure><h2 id="hromadne-operace" tabindex="-1">Hromadné operace <a class="header-anchor" href="#hromadne-operace" aria-label="Permalink to &quot;Hromadné operace&quot;">​</a></h2><p>Zaškrtněte úkoly, se kterými chcete pracovat. Zaškrtávacím polem v záhlaví mřížky vyberete všechny úkoly najednou – pak stačí odškrtnout ty, které do výběru nepatří.</p><p>Vedle zaškrtávacího pole v záhlaví se ukáže počet vybraných úkolů. Kliknutím na něj otevřete nabídku:</p><ul><li><strong>Export Excel</strong>, <strong>Export Excel s fotkami</strong>, <strong>Export PDF</strong>, <strong>Export PDF bez vyjádření</strong> – vyexportuje vybrané úkoly, viz <a href="/buildary-help-preview/tickets/exports">Export úkolů</a>,</li><li><strong>Smazat vybrané</strong> – smaže vybrané úkoly.</li></ul><figure class="shot" style="--w:600px;"><img src="'+e+'" alt="Tři vybrané úkoly a rozbalená nabídka hromadných operací s exporty a volbou Smazat vybrané" loading="lazy"></figure><p>Smazat můžete jen úkoly, ke kterým máte oprávnění – viz <a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a>.</p><h2 id="kanban" tabindex="-1">Kanban <a class="header-anchor" href="#kanban" aria-label="Permalink to &quot;Kanban&quot;">​</a></h2><p>Kanban zobrazí úkoly jako kartičky ve sloupcích podle stavu. Otevřete ho přepínačem <strong>Kanban</strong> nad mřížkou nebo v levém panelu volbou <strong>Kanban úkolů</strong>. Filtry v horním řádku zůstanou zachované, zobrazení <strong>Přehled</strong> ale v Kanbanu použít nejde.</p><figure class="shot" style="--w:760px;"><img src="'+d+'" alt="Kanban úkolů se sloupci Nezahájeno, Probíhá, Čeká se a Dokončeno a tlačítky Výběr sloupců, Tabulka a Kanban" loading="lazy"></figure><ul><li><strong>Výběr sloupců</strong> – vyberte, které stavy se zobrazí jako sloupce. K dispozici je až osm sloupců: <strong>Koncept</strong>, <strong>Nezahájeno</strong>, <strong>Probíhá</strong>, <strong>Čeká se</strong>, <strong>Dokončeno</strong>, <strong>Odloženo</strong>, <strong>Zamítnuto</strong> a <strong>Schváleno</strong>. U názvu sloupce je počet úkolů.</li><li><strong>Tlačítko +</strong> v záhlaví sloupců <strong>Koncept</strong>, <strong>Nezahájeno</strong>, <strong>Probíhá</strong> a <strong>Čeká se</strong> – založí nový úkol, který má předvyplněný stav podle sloupce.</li><li><strong>Přetažení kartičky</strong> do jiného sloupce – změní stav úkolu bez otevírání detailu. Přetáhnout jde jen do sloupce, který na stav logicky navazuje, a jen pokud máte ke změně stavu oprávnění – viz <a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a>.</li></ul><p>Kartička ukazuje předmět a číslo úkolu, prioritu, termín (u zpožděných úkolů i počet dní po termínu), zkratku kategorie a Řešitele. Štítky se na kartičkách zobrazují automaticky, filtrovat podle nich v Kanbanu nejde.</p><table tabindex="0"><thead><tr><th>Na kartičce</th><th>Co udělá</th></tr></thead><tbody><tr><td><strong>předmět</strong> úkolu</td><td>otevře detail úkolu</td></tr><tr><td>oranžová ikona bubliny</td><td>otevře celé vlákno vyjádření</td></tr><tr><td>menu <strong>⋮</strong></td><td><strong>Stažení do PDF</strong> nebo <strong>Smazat úkol</strong></td></tr></tbody></table><figure class="shot" style="--w:760px;"><img src="'+p+'" alt="Kanban s vyznačeným tlačítkem Výběr sloupců, tlačítkem plus, ikonou vyjádření, menu kartičky a přetažením kartičky do jiného sloupce" loading="lazy"></figure><p>Zpět na mřížku přepnete tlačítkem <strong>Tabulka</strong>.</p>',37)])])}const _=a(u,[["render",g]]);export{j as __pageData,_ as default};
